import ast, base64, hashlib, json, pathlib, sys, types, zlib
root=pathlib.Path(".")
result={"python":sys.version,"source":{},"product_imports":0,"product_tests":0}
for p in sorted(root.rglob("*")):
    if p.is_file():
        raw=p.read_bytes()
        result["source"][str(p)]={"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest(),"blob":hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()}
        if p.suffix==".py": ast.parse(raw)
tree=ast.parse((root/"resume_a733.py").read_bytes())
node=next(x for x in tree.body if isinstance(x,ast.FunctionDef) and x.name=="publish_large_record")
def wire(x): return (json.dumps(x,sort_keys=True,indent=2,ensure_ascii=True,allow_nan=False)+"\n").encode()
def identity(b): return {"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest(),"blob":hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest()}
def require(v,m):
    if not v: raise AssertionError(m)
saved={}
def publish(b,p):
    require(p not in saved, "duplicate record")
    saved[p]=b
    return identity(b)
scope={"c":types.SimpleNamespace(wire=wire,identity=identity,require=require,publish_text=publish),"zlib":zlib,"base64":base64,"hashlib":hashlib,"RECEIPT_CHUNKS":512*1024}
exec(compile(ast.Module(body=[node],type_ignores=[]),"<only-custody-publish-function>","exec"),scope)
cases=[
("small",{"x":1}),
("compressible",{"data":"a"*400000}),
("large",{"data":base64.b64encode(hashlib.shake_256(b"custody-transport-roundtrip-only").digest(800000)).decode("ascii")})
]
results=[]
for label,value in cases:
    saved.clear()
    ref=scope["publish_large_record"](value,label+".json")
    transport=json.loads(saved[ref["path"]])
    if transport.get("schema")=="hia.lossless-zlib-text-chunk-index.v1":
        rebuilt=bytearray()
        for i,row in enumerate(transport["chunks"]):
            require(row["index"]==i and row["offset"]==len(rebuilt),"offset")
            w=saved[row["wrapper"]["path"]]
            require(identity(w)=={k:row["wrapper"][k] for k in ("bytes","sha256","blob")},"wrapper")
            x=json.loads(w)
            part=base64.b64decode(x["data"],validate=True)
            require(len(part)==row["bytes"] and hashlib.sha256(part).hexdigest()==row["sha256"],"part")
            rebuilt.extend(part)
        require(identity(bytes(rebuilt))==transport["compressed"],"compressed")
        restored=zlib.decompress(rebuilt)
        require(identity(restored)==transport["original"],"original")
    elif transport.get("schema")=="hia.lossless-zlib-text-capsule.v1":
        restored=zlib.decompress(base64.b64decode(transport["data"],validate=True))
    else: restored=saved[ref["path"]]
    require(restored==wire(value),"all JSON bytes")
    results.append({"case":label,"exact_canonical_bytes":True,"records":len(saved),"max_record_bytes":max(map(len,saved.values())),"returned_path":ref["path"]})
require(results[-1]["records"]>1,"large case failed to exercise indexed chunks")
result["isolated_transport_roundtrips"]=results
result["syntax"]="PASS"
print(json.dumps(result,sort_keys=True))
